function methodsHTML(){const a=currentAsset();return `<div class="draw-methods" aria-label="Drawing mode">${Object.entries(METHODS).map(([k,[i,n]])=>`<button data-action="method:${k}" aria-label="${n}" title="${n}" aria-pressed="${k===ui.drawMode}" class="${k===ui.drawMode?'active':''}" ${!a.allowed?.includes(k)?'disabled':''}>${i}<small>${n}</small></button>`).join('')}</div>`}
