function assetTile(k,a){const selected=ui.drawAsset===k,kind=k.startsWith('panel_')?'panel':k.startsWith('surface_')?'surface':k.startsWith('annotation_')?'annotation':'asset',detail=k==='panel_sabre'?'4.00 × 2.00 m panel · special stagger':a.length?`${a.length} × ${a.width} m`:kind==='surface'?`Draw ${a.mode}`:kind==='annotation'?'Drawing tool':a.category||'Site asset',thumb=kind==='surface'?'⌁':kind==='annotation'?(k.endsWith('textBox')?'T':'◇'):C.assetIconSVG(k,a);return `<button class="asset-tile ${selected?'active':''}" data-action="choose:${k}" aria-pressed="${selected}" title="${esc(a.name)}"><span class="asset-thumb">${thumb}</span><span class="asset-tile-copy"><strong>${esc(a.name)}</strong><small>${esc(detail)}</small></span>${selected?'<b>✓</b>':''}</button>`}
